INSERT INTO count_lc_nullable
SELECT toUInt32(h2 % 1000000), h2 % 10000000, if(h % 10 = 0, NULL, concat('value_', toString(h3 % 1000))),
    if(h % 10 = 0, NULL, concat('https://example.com/some/longer/path/segment/', toString(h3 % 5000))),
    if(h % 5 = 0, NULL, toFixedString(leftPad(toString(h3 % 800), 8, '0'), 8))
FROM (SELECT cityHash64(number) AS h, cityHash64(number, 1) AS h2, cityHash64(number, 2) AS h3 FROM numbers_mt(100000000))
